import { API_BASE_URL } from '../config/api';

export interface Notification {
  id: string;
  title: string;
  body: string;
  read: boolean;
}

export async function fetchNotifications(): Promise<Notification[]> {
  const response = await fetch(`${API_BASE_URL}/notifications`);
  if (!response.ok) {
    throw new Error(`Failed to fetch notifications (status ${response.status})`);
  }
  return (await response.json()) as Notification[];
}

import { useState, useCallback } from 'react';
import { View, Text, FlatList, StyleSheet, ActivityIndicator, Pressable } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { fetchNotifications, Notification } from '../services/notifications';

const colors = {
  background: '#FFFFFF',
  text: '#1A1A1A',
  muted: '#6B7280',
  danger: '#DC2626',
  border: '#E5E7EB',
};

export function NotificationsScreen(): JSX.Element {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const items = await fetchNotifications();
      setNotifications(items);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load notifications');
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <SafeAreaView style={styles.safe}>
      <FlatList
        data={notifications}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.row}>
            <Text style={styles.title}>{item.title}</Text>
            <Text style={styles.body}>{item.body}</Text>
          </View>
        )}
        ListEmptyComponent={
          loading ? (
            <ActivityIndicator style={styles.center} />
          ) : error ? (
            <Pressable accessibilityRole="button" accessibilityLabel="Retry loading notifications" onPress={load}>
              <Text style={styles.error}>{error}</Text>
            </Pressable>
          ) : (
            <Text style={styles.empty}>No notifications yet</Text>
          )
        }
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.background },
  center: { marginTop: 24 },
  row: { padding: 16, borderBottomWidth: 1, borderBottomColor: colors.border },
  title: { fontSize: 16, fontWeight: '600', color: colors.text },
  body: { fontSize: 14, color: colors.muted, marginTop: 4 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24, padding: 12 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
